export const SIGNALS = ROWS.map(([id, cls, type, byte, bit, dir, name]) => ({
    id, controls: SL_PL, area: CLASS[cls], type, byte, bit, name,
    dir: dir || null, confidence: "manual", source: SOURCE,
}));

function resolveLabel(entry, db) {
    const [lo, hi] = entry.area.db;
    if (lo === hi) return entry.area.label;
    return `${entry.area.label} ${db - entry.area.offset}`;
}
const addressOf = (e, db) =>
    `DB${db}.${e.type}${e.byte}${e.bit === null ? "" : "." + e.bit}`;
const decorate = (e, db) => ({ ...e, resolvedLabel: resolveLabel(e, db), address: addressOf(e, db) });

/** Find signals at an exact address on a control. [] for an honest miss. */
export function lookupSignal({ control, db, byte, bit }) {
    return SIGNALS.filter((s) => {
        if (!s.controls.includes(control)) return false;
        const [lo, hi] = s.area.db;
        return db >= lo && db <= hi && s.byte === byte && s.bit === (bit ?? null);
    }).map((s) => decorate(s, db));
}

/** Free-text search over signal names for a control. */
export function searchSignals({ control, query }) {
    const q = String(query || "").trim().toLowerCase();
    if (q === "") return [];
    return SIGNALS.filter(
        (s) => s.controls.includes(control) && s.name.toLowerCase().includes(q)
    )
        .slice(0, 200)
        .map((s) => decorate(s, s.area.db[0]));
}
